  const decision_id = await ports.record("broadcast", b.id, "send_broadcast", {
    name: b.name,
    playbook_id: b.playbook_id,
    recipients: b.recipient_count,
    approved: true,
    scheduled_for: scheduledFor,
    ...movedFrom ? { moved_from: movedFrom } : {}
  });
